contexts=json.loads((src/'contexts.json').read_text())['records']; rows=[]
for r in contexts:
 o=r['source_ordinal']; cat,assessment,defects,tailtype=notes[o]; text=(src/r['context_file']).read_bytes();assert h(text)==r['context_sha256']
 w=next(w for w in r['all_original_window_predictions_and_skips'] if w['kind']=='chunk' and w['start']==r['failed_tail_start_character'])
 rows.append({'source_ordinal':o,'title':r['title'],'page_id':r['page_id'],'revision_id':r['revision_id'],'context_sha256':r['context_sha256'],'full_original_text_sha256':r['full_original_text_sha256'],'context_scope':'whole_short_document' if r['context_is_entire_short_document'] else 'last_2048_characters_only','classification':cat,'semantic_assessment':assessment,'visible_quality_defects_or_review_flags':defects,'failed_tail_content_type':tailtype,'original_whole_policy_pass':r['whole_prediction']['policy_pass'],'original_whole_english_probability':r['whole_prediction']['english_probability'],'original_failed_tail_prediction':w,'existing_screening_holds_preserved':r['existing_screening_holds'],'known_discovery_hold':r['known_discovery_hold'],'assessment_changes_policy_or_admission':False})
assert len(rows)==20 and set(notes)=={r['source_ordinal'] for r in rows}
out={'status':'INDEPENDENT_MANUAL_DEVELOPMENT_REVIEW_ALL20_NO_ACCEPTANCE','reviewer':'rights_review agent; direct reading of all20 exact frozen context files and their exact failed-tail substrings','source_folder':str(src),'source_hashes':pins,'records':rows,'summary':{'documents_reviewed':20,'whole_short_documents':13,'partial_last2048_contexts':7,'classification_counts':dict(collections.Counter(r['classification'] for r in rows)),'uncertain_category_count':0,'important_limits':['Classification is of observed context, not unseen full long documents.','Clear English is a language observation, not factual accuracy, prose-quality approval, legal clearance or admission.','Failure-conditioned sample of20 is development evidence; no overall corpus quality or rescue-rate estimate.','All original failures and holds remain effective. No detector rerun, text edit, replacement or policy implementation.']},'bounded_next_version_proposal':{'warrants_experiment':True,'purpose':'Measure whether original terminal chunks fail because they begin midword or consist of code/reference lists in otherwise English text, while retaining genuine multilingual detection.','proposed_experiment_only':['Freeze new version and bounded input/profile before any scoring; preserve existing baseline outputs and every raw terminal score.','Compare a terminal context ending at the exact same document end, extended backward to at most1024 original Unicode characters, only for eligible original terminal chunks shorter than1024; no rewriting, dropping or threshold reduction.','Keep whole and every prior eligible nonterminal score unchanged. Preserve all semantic/rights/structure/factual/dedup/leakage holds independently.','Track original-terminal and anchored predictions separately, with exact offsets, raw/projected hashes and score coverage. Do not convert a diagnostic pass automatically into admitted data.','Use all20 frozen examples as explicit development challenges, especially57271 Latin tail,24354 Marathi,50948 Albanian,66657 Arabic. Whole-English-pass alone is insufficient:57271 already passes whole scoring.','Treat code, bibliographies, navigation and botanical/game-name lists as separate content-quality cases, not foreign-language evidence or automatically useful English.','Require independent review of changed decisions and a fresh frozen representative sample before any policy adoption.'], 'not_proposed':['No anchored detector run now.','No blanket rescue of7406 failures.','No threshold relaxation or assumption that all short-tail failures are false positives.','No removal of genuine foreign-language tail or code merely to obtain passing scores.']},'new_admitted_documents':0,'new_admitted_tokens':0,'model_operations':False}
(base/'assessment.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'classification_counts':out['summary']['classification_counts'],'assessment_sha256':h((base/'assessment.json').read_bytes()),'bytes':(base/'assessment.json').stat().st_size},indent=2))
